local MaidCoffeePreviewRateDialog = Class('MaidCoffeePreviewRateDialog')

function MaidCoffeePreviewRateDialog:__init()
    ---@type integer 选中的卡池索引
    self._selectIndex = nil
    ---@type integer 当前卡池类型
    self._poolType = nil
    ---@type table
    self.pools = nil
end

function MaidCoffeePreviewRateDialog:__delete()
    self._selectIndex = nil
    self._poolType = nil
    self.pools = nil
end

function MaidCoffeePreviewRateDialog:Awake()
    self.controller.IsAutoHandleNavBar = false

    SetButtonAction(self.ButtonClose, function()
        UIModule.CloseDialog(self.controller)
    end)
end

function MaidCoffeePreviewRateDialog:OnInitialize()
    return CoWaitDo(function()
        local initParams = self.controller.Argument.parameters
        local pools = initParams.data
        self._selectIndex = checkInt(initParams.SelectIndex)
        self._poolType = checkInt(initParams.PoolType)
        self.pools = pools
        self._campId = table.takeFirst(pools).poolId
    end)
end

function MaidCoffeePreviewRateDialog:OnFinalize()
    return CoWaitDo(function()
        self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
        self:Delete()
    end)
end

function MaidCoffeePreviewRateDialog:OnShow()
    return CoWaitDo(function()
        local pool = table.takeFirst(self.pools)
        self:InitPool(pool)
    end)
end

---@param pool GachaponDojo
function MaidCoffeePreviewRateDialog:InitPool(pool)
    ---@param t GachaponPreviewDojo[]
    ---@return GachaponPreviewDojo[]
    local function unique(t)
        local check = {}
        local n = {}
        local idx = 1
        for k, v in pairs(t) do
            if not check[v.itemId] then
                n[idx] = v
                idx = idx + 1
                check[v.itemId] = true
            end
        end
        return n
    end
    self:InitMember(unique(pool.preview), pool)
end

function MaidCoffeePreviewRateDialog:InitRarePro(rares)
    print(table.dump(rares))
    KTool.SetActive(self.RarePro.gameObject, false)
    local cnt = table.count(rares)
    self.ProLayout.enabled = true
    GachaponUtils.ResizeContent(self.ProLayout.transform, cnt, self.RarePro)
    local idx = 0
    for i = 1, #GachaponConstants.RareOrder do
        local key = GachaponConstants.RareOrder[i]
        if isSet(rares, key) then
            local rareIns = self.ProLayout.transform:GetChild(idx)
            self:UpdateRarePro(rareIns, GachaponConstants.RareOrder[i], rares[key])
            idx = idx + 1
        end
    end
end

function MaidCoffeePreviewRateDialog:UpdateRarePro(trans, rareNum, probably)
    local bg = trans:Find("bg").gameObject:GetComponent(typeof(ImageComp))

    bg.color = GachaponUtils.GetRareColor(self._poolType, rareNum)
    local pro = trans:Find("pro").gameObject:GetComponent(typeof(TextComp))
    pro.text = tostring(probably) .. "%"
    if not GachaponUtils.IsEquipType(self._poolType) then
        local rare = trans:Find("rare").gameObject:GetComponent(typeof(TextComp))
        rare.text = GachaponConstants.RareTips[rareNum]

    end
end

---@param members GachaponPreviewDojo[]
---@param pool GachaponDojo
function MaidCoffeePreviewRateDialog:InitMember(members, pool)
    ---@type table<integer, GoodsVo[]>
    local filter = {}
    ---@type table<integer, GoodsVo[]>
    local UpFilter = {}
    ---@type table<integer, GachaponPreviewDojo>
    local memberMap = {}
    for i = 1, #members do
        local member, rare = self:GetMembersData(members[i].itemId)
        if not isSet(filter, rare) then
            filter[rare] = {}
        end
        if not isSet(UpFilter, rare) then
            UpFilter[rare] = {}
        end
        table.insert(filter[rare], member)
        if members[i].isUp == 1 then
            table.insert(UpFilter[rare], member)
        end
        memberMap[checkInt(member.refId)] = members[i]
    end
    ---显示概率一览
    local names = MaidCoffeeConstants.QualityName
    local gridLayoutTrans = self.probability.transform:Find("GridLayout")
    local rareNodeTrans = self.probability.transform:Find("RareNode")
    KTool.DestroyGameObjectChildren(gridLayoutTrans.gameObject, false)
    local poolRates = {}
    for i = #names, 1, -1 do
        local t = filter[i]
        if t then
            local pro = 0
            if pool.rates[tostring(i)] then
                pro = checkNumber(pool.rates[tostring(i)])
            end
            poolRates[i] = pro
            ----@type UnityEngine.GameObject
            local go = KTool.Instantiate(gridLayoutTrans.gameObject, rareNodeTrans.gameObject, false)
            KTool.SetActive(go, true)
            local qualityBg = go.transform:Find("ImgQualityBg")
            local textNumber = go.transform:Find("TextNumber")
            local textType = go.transform:Find("TextType")
            CfUtils.SetUISwitchImage(qualityBg.gameObject, i + 2)
            CfUtils.FillText(textNumber.gameObject, attribute_format(1, pro))
            CfUtils.SetUISwitchText(textType.gameObject, i)
        end
    end
    KTool.SetActive(self.MemberBlock, false)
    KTool.SetActive(self.LineGroup, false)
    KTool.SetActive(self.GoodNode, false)
    KTool.SetActive(self.MemberIntro, false)
    local RectTransform = typeof(RectTransform)
    local memberGroupRect = self.MemberGroup.gameObject:GetComponent(RectTransform)

    local descrText = pool.poolDesc
    KTool.SetActive(self.ScrollBar.gameObject, true)
    self:InitEnsurance(descrText)
    -- self:InitRarePro(poolRates)
    cs_coroutine.yield_return(Yielders.EndOfFrame)
    local keys = table.keys(filter)
    for i = #keys, 1, -1 do
        local key = keys[i]
        if isSet(filter, key) then
            local rectTrans = GameObject.Instantiate(self.MemberBlock.gameObject, memberGroupRect):GetComponent(RectTransform)
            KTool.SetActive(rectTrans.gameObject, true)
            local memberRect = nil
            -- local memberRect = GameObject.Instantiate(self.MemberIntro.gameObject,memberGroupRect):GetComponent(RectTransform)
            -- KTool.SetActive(memberRect.gameObject, true)
            --print( table.serialize(filter[key]) , table.serialize(UpFilter[key]) , key )
            self:UpdateMemberBlock(memberRect, rectTrans, filter[key], memberMap, key, poolRates[key] or poolRates[tostring(key)], names)
        end
    end
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
    CfUtils.SetCanvasGroupAlpha(self.ScrollBar.gameObject, 1)
    --cs_coroutine.yield_return(Yielders.EndOfFrame)
    --KTool.SetActive(self.ScrollBar.gameObject, true)
end

---@param id integer
---@return MaidCoffeeCatRollConfigVo, integer
function MaidCoffeePreviewRateDialog:GetMembersData(id)
    local member, rare
    ---@type MaidCoffeeCatRollConfigVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting4000, 'MaidCoffeeCatRollConfigVo', id)
    if vo then
        member = vo
        rare = checkNumber(vo.quality)
    end
    return member, rare
end

---@param trans UnityEngine.Transform
---@param compTable table 类型
---@return UnityEngine.Component | nil
function MaidCoffeePreviewRateDialog:GetComponent(trans, compTable)
    local object = trans:Find(compTable.path)
    if isNull(object) then
        return
    end
    return object.gameObject:GetComponent(compTable.componentName)
end


---@param memberIntroTrans UnityEngine.RectTransform @ 卡牌名字节点
---@param memberBlockTrans UnityEngine.RectTransform @ 卡牌头像节点
---@param members GoodsVo[] @ 全部卡牌列表
---@param previewMap table<integer, GachaponPreviewDojo> @ up的卡牌id
---@param rateId integer @ 品质id
---@param rateValue number @ 品质id
---@param names table @ 名称
function MaidCoffeePreviewRateDialog:UpdateMemberBlock(memberIntroTrans, memberBlockTrans, members, previewMap, rateId, rateValue, names)
    local memberChildrenPath = {
        rate = { path = "TittleGroup/TextType", componentName = typeof(UISwitchText) },
        bg = { path = "TittleGroup/ImgBg", componentName = typeof(UISwitchImage) },
        value1 = { path = "TittleGroup/TextProbability", componentName = typeof(UISwitchImage) },
        value2 = { path = "ProbabilityUpNode/TextDesc", componentName = typeof(TextComp) },
        Content = { path = "Content", componentName = typeof(RectTransform) },
        introTitle = { path = "Image/introTitle", componentName = typeof(TextComp) }, -- intro child
        introMain = { path = "introMain", componentName = typeof(TextComp) }, -- intro child
    }

    -- 品质标题字
    local rate = self:GetComponent(memberBlockTrans, memberChildrenPath.rate)
    if rate then
        rate.text = names[rateId]
    end

    -- 品质概率值
    ---@type Game.Native.Common.UISwitchImage
    local value1 = self:GetComponent(memberBlockTrans, memberChildrenPath.value1)
    if value1 then
        value1.Status = rateId + 2
    end
    ---@type TMPro.TextMeshProUGUI
    local value2 = self:GetComponent(memberBlockTrans, memberChildrenPath.value2)
    if value2 then
        local v = string.format('%g%%', checkInt(rateValue * 1000) / 10)
        value2.text = string.format('占出率的%s', v)
    end

    -- 品质标题背景条
    ---@type Game.Native.Common.UISwitchImage
    local bg = self:GetComponent(memberBlockTrans, memberChildrenPath.bg)
    if bg then
        bg.Status = rateId + 2
    end

    local voCount = #members
    local Content = self:GetComponent(memberBlockTrans, memberChildrenPath.Content)
    if voCount ~= 0 and rateId >= 4 then
        cs_coroutine.yield_return(Yielders.EndOfFrame)
        GachaponUtils.ResizeContent(Content, voCount, self.RoleCell.gameObject)
        for i = 1, voCount do
            ---@type MaidCoffeeCatRollConfigVo
            local cardVo = members[i]
            local memberIns = Content:GetChild(i - 1)
            self:UpdateCardCell(memberIns, cardVo, previewMap[cardVo.refId])
        end
    else
        CfUtils.SetActive(Content, false)
    end

    -- update intro node
    if memberIntroTrans then
        -- 提示
        local introTitle = self:GetComponent(memberIntroTrans, memberChildrenPath.introTitle)
        if introTitle then
            introTitle.text = localize("可能出现的武装")
        end

        -- 名字集
        local introMain = self:GetComponent(memberIntroTrans, memberChildrenPath.introMain)
        if introMain then
            local names = ""
            for i = 1, #members do
                if i > 1 then
                    names = names .. "/"
                end
                names = names .. members[i].name
            end
            introMain.text = names
        end

        CfUtils.SetActive(memberIntroTrans, true)
    end
end

