---@param desc string
function MaidCoffeePreviewRateDialog:InitEnsurance(desc)
    KTool.SetActive(self.Ensurance:Find("EnsuranceMain").gameObject, false)
    local text = self.Ensurance:Find("EnsuranceMain").gameObject:GetComponent(typeof(TextComp))
    text.text = desc
    cs_coroutine.yield_return(Yielders.EndOfFrame)
    KTool.SetActive(self.Ensurance:Find("EnsuranceMain").gameObject, true)
end

